[Form]
public class AVASalesLineBackOrderReservation extends FormRun
{
    Args                        frmArgs;
    AVASalesLineBackOrderTmp    frmAVASalesLineBackOrderTmpArgs;
    FormRun                     frmFormRunCaller;
    SalesLine                   frmSalesLine;
    SalesLine                   frmSalesLineArgs;
    SalesLine                   frmSalesLineItemSet;
    SalesLine                   frmSalesLineComponent;
    InventTable                 frmInventTable;
    InventItemSalesSetup        frmInventItemSalesSetup;
    InventTable                 frmInventTableItemSet;
    InventItemSalesSetup        frmInventItemSalesSetupItemSet;
    InventTable                 frmInventTableComponent;
    InventItemSalesSetup        frmInventItemSalesSetupComponent;

    SalesQty                    frmReservedPhysicalInSalesUnit;
    InventQty                   frmReservedPhysical;
    SalesQty                    frmReservedPhysicalInSalesUnitItemSet;
    InventQty                   frmReservedPhysicalItemSet;
    SalesQty                    frmReservable;
    SalesQty                    frmItemSetQtyFactor;
    SalesQty                    remainInventQtyItemSet;


    boolean                     frmItemSetMode;

    Qty     reservedQty;
    Qty     toReserveAvailableQty;
    Qty     canBeReserved;
    Qty     reserveNow;
    Qty     remainInventQty;
    Qty     multipleQty;


}

/// <summary>
///    AVA <c>init</c> method.
/// </summary>
public void init()
{


    frmItemSetQtyFactor = 1;

    super();
    frmArgs             = new Args();
    frmArgs             = this.args();
    if(frmArgs)
    {
        if (frmArgs.caller())
        {
            frmFormRunCaller = frmArgs.caller();
            if(frmFormRunCaller.name() == formStr(AVASalesLineBackOrder))
            {
                if(frmArgs.record().TableId == tableNum(AVASalesLineBackOrderTmp))
                {
                    frmAVASalesLineBackOrderTmpArgs = frmArgs.record();
                    // get corresponding SalesLine from tmp
                    frmSalesLineArgs                = frmAVASalesLineBackOrderTmpArgs.salesLine();
                    // set actual form SalesLine to handle in form to calling SalesLine
                    frmSalesLine                    = frmSalesLineArgs;
                    frmInventTable                          = InventTable::find(frmSalesLine.ItemId);
                    frmInventItemSalesSetup                 = InventItemSalesSetup::findDefault(frmInventTable.ItemId);

                    if(frmSalesLine.AVAItemSetComponent)
                    {
                        // Item set
                        frmSalesLineItemSet                 = frmSalesLine.avaItemSetSalesLine();
                        frmInventTableItemSet               = InventTable::find(frmSalesLineItemSet.ItemId);
                        frmInventItemSalesSetupItemSet      = InventItemSalesSetup::findDefault(frmInventTableItemSet.ItemId);
                        // Item set component
                        frmSalesLineComponent               = SalesLine::findRecId(frmSalesLine.RecId);
                        frmInventTableComponent             = InventTable::find(frmSalesLineComponent.ItemId);
                        frmInventItemSalesSetupComponent    = InventItemSalesSetup::findDefault(frmInventTableComponent.ItemId);

                        frmItemSetMode                      = true;
                    }
                    else
                    {
                        frmSalesLineComponent               = null;
                        frmSalesLineItemSet                 = null;
                        frmItemSetMode                      = false;
                    }

                    this.calcReservableQty();
                }
            }
        }
    }
    this.setSalesLinesValues();
}

/// <summary>
/// N.Freidenberger 27.09.2024
/// </summary>
public void calcReservableQty()
{
    if (frmItemSetMode)
    {
        Qty  locCompReservedQty; 


        locCompReservedQty        = frmSalesLineComponent.reservedPhysicalInSalesUnit();
        reservedQty               = frmSalesLineComponent.AVAItemSetCompQtyPerSerie != 0 ? locCompReservedQty * frmSalesLineComponent.AVAItemSetSerie / frmSalesLineComponent.AVAItemSetCompQtyPerSerie : locCompReservedQty * frmSalesLineComponent.AVAItemSetSerie;
        toReserveAvailableQty     = frmSalesLineItemSet.AVAgetMinAvailToReserveQtyFromItemSetComponents(true,reservedQty);
        multipleQty               = frmInventItemSalesSetupItemSet.MultipleQty;
        remainInventQty           = frmSalesLineComponent.AVAItemSetCompQtyPerSerie != 0 ? frmSalesLineComponent.RemainInventPhysical * frmSalesLineComponent.AVAItemSetSerie / frmSalesLineComponent.AVAItemSetCompQtyPerSerie : frmSalesLineComponent.RemainInventPhysical * frmSalesLineComponent.AVAItemSetSerie;

    }
    else
    {
        reservedQty               = frmSalesLine.reservedPhysicalInSalesUnit();
        toReserveAvailableQty     = (frmSalesLine.RemainInventPhysical - reservedQty) < frmSalesLine.AVAAvailToReserveQty() ? (frmSalesLine.RemainInventPhysical - reservedQty) : frmSalesLine.AVAAvailToReserveQty();
        multipleQty               = frmInventItemSalesSetup.MultipleQty;
        remainInventQty           = frmSalesLine.RemainInventPhysical;
    }
    canBeReserved = toReserveAvailableQty +  reservedQty;
    reserveNow    = canBeReserved - (canBeReserved mod multipleQty); 
}

/// <summary>
///    AVA <c>setSalesLinesValues</c> method.
/// </summary>
public void setSalesLinesValues()
{
    // ItemSetGroup
    if(frmItemSetMode)
    {
        ItemSetGroup.visible(true);
        ItemSetComponentGroup.visible(true);
    }
    else
    {
        SalesLineGroup.visible(true);
        ReserveQtyGrp.caption("@NDX:NXAQuantites");
    }

    InventTable_ItemId.text(frmSalesLine.ItemId);
    SalesLineGrp_RemainInventPhys.realValue(frmSalesLine.RemainInventPhysical);
    SalesLineGrp_Unit.text(frmSalesLine.SalesUnit);
    SalesLineGrp_MultipleQty.realValue(frmInventItemSalesSetup.MultipleQty);

    ItemSetComponentGroup_ItemId.text(frmSalesLineComponent.ItemId);
    SalesLineComp_RemainSalesPhysical.realValue(frmSalesLineComponent.RemainInventPhysical);
    SalesLineComp_SalesUnit.text(frmSalesLineComponent.SalesUnit);
    frmReservedPhysicalInSalesUnit = frmSalesLineComponent.reservedPhysicalInSalesUnit();
    SalesLineComp_ReservedSalesUnit.realValue(frmReservedPhysicalInSalesUnit);

    ItemSetGroup_ItemId.text(frmSalesLineItemSet.ItemId);      
    ItemSetGroup_RemainInventPhys.realValue(remainInventQty);
    ItemSetGroup_Unit.text(frmSalesLineItemSet.SalesUnit);
    ItemSetGroup_MultipleQty.realValue(frmInventItemSalesSetupItemSet.MultipleQty);


    ReservedQtyCtrl.realValue(reservedQty);
    ToReserveAvailQtyCtrl.realValue(toReserveAvailableQty);
    canBeReservedCtrl.realValue(canBeReserved);
    reserveNowCtrl.realValue(reserveNow);
}

/// <summary>
///    AVA <c>closeOk</c> method.
/// </summary>
public void closeOk()
{
    FormRun             locFormRunCaller;
    boolean             canBeClose = true;

    locFormRunCaller = frmArgs.caller();
    reserveNow = reserveNowCtrl.realValue();

    if (reserveNow > remainInventQty)
    {
        if (frmItemSetMode)
        {
            canBeClose = checkFailed("@NDX:NXABiggerEsRemainQtyErrorSet");
        }
        else
        {
            canBeClose = checkFailed("@NDX:NXABiggerEsRemainQtyError");
        }
    }

    if (reserveNow  > (toReserveAvailableQty + ReservedQty))
    {
        canBeClose = checkFailed("@NDX:NXANorReservedQtyError");
    }

    if ((reserveNow mod multipleQty) != 0)
    {
        canBeClose = checkFailed("@NDX:NXAReserveNowMultipleQtyError");
    }

    if(!canBeClose)
    {
        return;
    }

    super();


    if(frmItemSetMode)
    {
        SalesLine               locCompSalesLine;
        real                    compFactor;
        Qty                     reserveNowComp;

        while select locCompSalesLine
            where locCompSalesLine.SalesId          == frmSalesLineItemSet.SalesId
               && locCompSalesLine.AVAItemSetParent == frmSalesLineItemSet.InventTransId
        {
            compFactor = locCompSalesLine.AVAItemSetSerie != 0 ? locCompSalesLine.AVAItemSetCompQtyPerSerie / locCompSalesLine.AVAItemSetSerie : locCompSalesLine.AVAItemSetCompQtyPerSerie;
            //reserveNowComp = (toReserveAvailableQty * compFactor) - locCompSalesLine.reservedPhysicalInSalesUnit();
            //reserveNowComp = (toReserveAvailableQty * compFactor);
            reserveNowComp = ((reserveNow - reservedQty) * compFactor);
            locCompSalesLine.avaReserveSalesLine(locCompSalesLine,reserveNowComp);
        }
    }
    else
    {
        frmSalesLine.avaReserveSalesLine(frmSalesLine,reserveNow - reservedQty);    
    }


    if (formHasMethod(locFormRunCaller, literalStr(afterAVASalesLineBackOrderReservation)))
    {
        locFormRunCaller.afterAVASalesLineBackOrderReservation(frmAVASalesLineBackOrderTmpArgs);
    }


}

/// <summary>
///    AVA <c>clicked</c> method.
/// </summary>
public void clicked()
{
    super();

    ttsbegin;
    frmAVASalesLineBackOrderTmpArgs.selectForUpdate(true);
    frmAVASalesLineBackOrderTmpArgs.KCS_SOCPickingReleaseIndicator = NoYes::No;
    frmAVASalesLineBackOrderTmpArgs.update();
    ttscommit;
}
